 95	/// [`crate::read_identity`]'s `pyproject.toml` implementation: parses
 96	/// `source` and extracts a package name (PEP 621, falling back to Poetry
 97	/// then Flit -- see [`python_package_name`]) plus a
 98	/// [`crate::VersionSource::Literal`] version (PEP 621 `project.version`,
 99	/// falling back to Poetry's `tool.poetry.version` and Flit's
100	/// `tool.flit.metadata.version`; see [`python_version`]). Python has no
101	/// workspace-inherited-version concept analogous to Cargo's, and a PEP 621
102	/// `dynamic = ["version"]` package has no static version to report, so it
103	/// falls through to `None`.
104	pub(crate) fn identity_from_source(source: &str, path: &Path) -> Result<crate::ManifestIdentity, ManifestError> {
105	    let clean = source.strip_prefix('\u{FEFF}').unwrap_or(source);
106	    let doc: toml_edit::DocumentMut = clean.parse().map_err(|e: toml_edit::TomlError| ManifestError::Parse {
107	        path: path.to_path_buf(),
