118	/// A parsed PEP 508 dependency specifier, e.g.
119	/// `"requests[security,socks]>=2.0; python_version >= '3.8'"`.
120	///
121	/// The single implementation shared by `iter_dependencies`, `update_dependency_spec` and
122	/// `update_optional_dependencies` for the marker/operator/extras split.
123	///
124	/// `render` produces a normalized textual form (no space around `[...]`,
125	/// extras comma-joined with no interior space, no space between the
126	/// name/extras and the version spec, and a single `;` directly before the
127	/// marker with no extra whitespace). This is not necessarily byte-identical
128	/// to arbitrary input formatting, but `Requirement::parse(&r.render())`
129	/// always reproduces a `Requirement` equal to `r` when `r` itself came from
130	/// `parse` -- see the `requirement_parse_render_parse_is_idempotent`
131	/// property test.
132	#[derive(Clone, Debug, PartialEq, Eq)]
133	pub struct Requirement {
134	    pub name: String,
135	    pub extras: Vec<String>,
136	    /// The version-constraint clause(s) verbatim (e.g. `">=1.0,<2.0"` or
137	    /// `"==1.2.3"`) -- `None` when the requirement carries no version
138	    /// constraint at all (a bare name, optionally with extras/marker).
139	    pub spec: Option<String>,
140	    /// The clause was written in the legacy PEP 508 form `name (>=1.0)`, and renders back that way.
141	    pub parenthesized: bool,
142	    /// The marker expression (without the leading `;` or surrounding
143	    /// whitespace), e.g. `"python_version >= '3.8'"` -- `None` when absent.
144	    pub marker: Option<String>,
145	}
146	
147	impl Requirement {
148	    /// Parses a single PEP 508 requirement string. Returns `None` when no
149	    /// package name can be extracted (e.g. an empty string, or a string
150	    /// that is entirely a marker/version clause with nothing before it).
151	    pub fn parse(s: &str) -> Option<Self> {
152	        let s = s.trim();
153	
154	        let mut halves = s.splitn(2, ';');
155	        let spec_part = halves.next().unwrap_or("").trim();
156	        let marker = halves
157	            .next()
158	            .map(str::trim)
159	            .filter(|m| !m.is_empty())
160	            .map(str::to_string);
161	
162	        let name_end = spec_part
163	            .find(|c: char| c.is_whitespace() || "([@,<>=!~".contains(c))
164	            .unwrap_or(spec_part.len());
165	        let name = spec_part[..name_end].to_string();
166	        let mut rest = spec_part[name_end..].trim_start();
167	
168	        let mut extras = Vec::new();
169	        if rest.starts_with('[') {
170	            let end = rest.find(['<', '>', '=', '!', '~', '(', '@']).unwrap_or(rest.len());
171	            // Strip exactly the one bracket pair `render` writes, so a stray `[` or `]` inside survives a round trip.
172	            let inner = rest[1..end].trim_end();
173	            let inner = inner.strip_suffix(']').unwrap_or(inner);
174	            extras = inner
175	                .split(',')
176	                .map(str::trim)
177	                .filter(|e| !e.is_empty())
178	                .map(str::to_string)
179	                .collect();
180	            rest = rest[end..].trim_start();
181	        }
182	
183	        // Text after the name that is not a clause is dropped.
184	        let (spec, parenthesized) = if let Some(inner) = rest.strip_prefix('(') {
185	            let inner = inner.trim_end();
186	            let inner = inner.strip_suffix(')').unwrap_or(inner).trim();
187	            (!inner.is_empty())
188	                .then(|| inner.to_string())
189	                .map_or((None, false), |s| (Some(s), true))
190	        } else if rest.starts_with(['<', '>', '=', '!', '~', '@']) {
191	            (Some(rest.to_string()), false)
192	        } else {
193	            (None, false)
194	        };
195	
196	        if name.is_empty() {
197	            return None;
198	        }
199	
200	        Some(Requirement {
201	            name,
202	            extras,
203	            spec,
204	            parenthesized,
205	            marker,
206	        })
207	    }
208	
209	    /// Renders back to PEP 508 text -- see the struct's doc comment for the
210	    /// normalization this applies relative to arbitrary input formatting.
211	    pub fn render(&self) -> String {
212	        let mut out = self.name.clone();
213	        if !self.extras.is_empty() {
214	            out.push('[');
215	            out.push_str(&self.extras.join(","));
216	            out.push(']');
217	        }
218	        match (&self.spec, self.parenthesized) {
219	            (Some(spec), true) => out.push_str(&format!(" ({spec})")),
220	            (Some(spec), false) if spec.starts_with('@') => out.push_str(&format!(" {spec}")),
221	            (Some(spec), false) => out.push_str(spec),
222	            (None, _) => {}
223	        }
224	        if let Some(marker) = &self.marker {
225	            out.push(';');
226	            out.push_str(marker);
227	        }
228	        out
229	    }
230	}
