232	/// Splits a bare `major[.minor[.patch]]` version core (no pre-release/local
233	/// suffix, at most three dotted integer components) into its components.
234	/// Returns `None` for anything else -- a caret/tilde/wildcard clause whose
235	/// core doesn't fit this shape (e.g. `^1.2.3-beta`) is not normalized here;
236	/// the caller falls through to a raw PEP 440 parse attempt (which will fail)
237	/// and ultimately an opaque fallback, rather than mis-normalizing it.
238	fn parse_version_core(s: &str) -> Option<(u64, Option<u64>, Option<u64>)> {
239	    let mut parts = s.split('.');
240	    let major: u64 = parts.next()?.parse().ok()?;
241	    let minor = parts.next().map(str::parse).transpose().ok()?;
242	    let patch = parts.next().map(str::parse).transpose().ok()?;
243	    if parts.next().is_some() {
244	        return None;
245	    }
246	    Some((major, minor, patch))
247	}
248	
249	/// Expands a Poetry caret clause's version core (the part after `^`) into an
250	/// equivalent PEP 440 range. Caret allows changes that do not modify the
251	/// leftmost non-zero component of `major.minor.patch` -- see
252	/// <https://python-poetry.org/docs/dependency-specification/#caret-requirements>.
253	fn normalize_caret(rest: &str) -> Option<String> {
254	    let (major, minor, patch) = parse_version_core(rest)?;
255	    let lower = format!("{major}.{}.{}", minor.unwrap_or(0), patch.unwrap_or(0));
256	
257	    let upper = if major > 0 {
258	        format!("{}.0.0", major + 1)
259	    } else if let Some(min) = minor {
260	        if min > 0 {
261	            format!("0.{}.0", min + 1)
262	        } else if let Some(pat) = patch {
263	            format!("0.0.{}", pat + 1)
264	        } else {
265	            "0.1.0".to_string()
266	        }
267	    } else {
268	        "1.0.0".to_string()
269	    };
270	
271	    Some(format!(">={lower},<{upper}"))
272	}
273	
274	/// Expands a Poetry tilde clause's version core (the part after `~`) into an
275	/// equivalent PEP 440 range. Tilde allows patch-level changes when a minor
276	/// version is given, otherwise major-level changes -- see
277	/// <https://python-poetry.org/docs/dependency-specification/#tilde-requirements>.
278	fn normalize_tilde(rest: &str) -> Option<String> {
279	    let (major, minor, patch) = parse_version_core(rest)?;
280	    let lower = format!("{major}.{}.{}", minor.unwrap_or(0), patch.unwrap_or(0));
281	    let upper = match minor {
282	        Some(min) => format!("{major}.{}.0", min + 1),
283	        None => format!("{}.0.0", major + 1),
284	    };
285	    Some(format!(">={lower},<{upper}"))
286	}
287	
288	/// Expands a bare Poetry wildcard clause (`1.*`, `1.2.*`) into an equivalent
289	/// PEP 440 range. Does not handle wildcards already attached to an explicit
290	/// operator (`==1.2.*`, `!=1.2.*`) -- those are valid PEP 440 as-is and must
291	/// not reach this function (see `normalize_poetry_clause`).
292	fn normalize_wildcard(clause: &str) -> Option<String> {
293	    let core = clause.strip_suffix(".*")?;
294	    if core.is_empty() {
295	        return None;
296	    }
297	    let mut parts = core.split('.');
298	    let major: u64 = parts.next()?.parse().ok()?;
299	    match parts.next() {
300	        None => Some(format!(">={major}.0.0,<{}.0.0", major + 1)),
301	        Some(minor_str) => {
302	            if parts.next().is_some() {
303	                return None;
304	            }
305	            let minor: u64 = minor_str.parse().ok()?;
306	            Some(format!(">={major}.{minor}.0,<{major}.{}.0", minor + 1))
307	        }
308	    }
309	}
310	
311	/// Normalizes a single comma-separated clause of a Poetry version
312	/// constraint. Only bare caret/tilde/wildcard clauses are rewritten; a
313	/// clause that's already PEP 440-compatible (`>=1.2`, `~=1.2.3`, `==1.2.*`)
314	/// passes through unchanged, since Poetry accepts standard PEP 440 syntax
315	/// verbatim alongside its own caret/tilde/wildcard extensions.
316	fn normalize_poetry_clause(clause: &str) -> String {
317	    if clause == "*" {
318	        return String::new();
319	    }
320	    if let Some(rest) = clause.strip_prefix('^') {
321	        if let Some(normalized) = normalize_caret(rest) {
322	            return normalized;
323	        }
324	    } else if let Some(rest) = clause.strip_prefix('~') {
325	        // Distinguish Poetry's bare tilde ("~1.2.3") from PEP 440's
326	        // compatible-release operator ("~=1.2.3"), which is already valid.
327	        if !rest.starts_with('=')
328	            && let Some(normalized) = normalize_tilde(rest)
329	        {
330	            return normalized;
331	        }
332	    } else if clause.starts_with(|c: char| c.is_ascii_digit())
333	        && clause.contains('*')
334	        && let Some(normalized) = normalize_wildcard(clause)
335	    {
336	        return normalized;
337	    }
338	    clause.to_string()
339	}
340	
341	/// Normalizes a Poetry-style version constraint -- which allows caret (`^`),
342	/// tilde (`~`), and wildcard (`*`) syntax on top of PEP 440, see
343	/// <https://python-poetry.org/docs/dependency-specification/#version-constraints>
344	/// -- into a comma-joined PEP 440 range string that `pep440_rs` can parse
345	/// directly.
346	///
347	/// Each comma-separated clause is normalized independently, so compound
348	/// constraints like `^1.2,!=1.2.5` are handled correctly. A clause this
349	/// normalizer doesn't recognize (or can't decompose, e.g. a caret applied to
350	/// a pre-release version) passes through unchanged; the subsequent
351	/// `VersionReq::parse` attempt then fails on it, and the caller falls back
352	/// to an opaque dependency entry rather than silently dropping the
353	/// dependency.
354	fn normalize_poetry_version_spec(raw: &str) -> String {
355	    raw.split(',')
356	        .map(str::trim)
357	        .filter(|clause| !clause.is_empty())
358	        .map(normalize_poetry_clause)
359	        .filter(|clause| !clause.is_empty())
360	        .collect::<Vec<_>>()
361	        .join(",")
362	}
