457	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = DependencyEntry> + '_> {
458	        let mut entries = Vec::new();
459	
460	        // 1. PEP 621 [project].dependencies (array of requirement strings)
461	        if let Some(deps) = self
462	            .document
463	            .get("project")
464	            .and_then(|p| p.get("dependencies"))
465	            .and_then(|d| d.as_array())
466	        {
467	            entries.extend(requirement_entries(
468	                deps,
469	                DepKind::Runtime,
470	                &DepContainer::ProjectDependencies,
471	            ));
472	        }
473	
474	        // 1b. PEP 621 [project.optional-dependencies]: extras ship in the published metadata, so a
475	        // pin there goes stale exactly like a runtime one.
476	        if let Some(extras) = self
477	            .document
478	            .get("project")
479	            .and_then(|p| p.get("optional-dependencies"))
480	            .and_then(|d| d.as_table_like())
481	        {
482	            for (extra, group) in extras.iter() {
483	                if let Some(requirements) = group.as_array() {
484	                    entries.extend(requirement_entries(
485	                        requirements,
486	                        DepKind::Optional,
487	                        &DepContainer::Extra(extra.to_string()),
488	                    ));
489	                }
490	            }
491	        }
492	
493	        // 2. Poetry [tool.poetry.dependencies]
494	        if let Some(table) = self
495	            .document
496	            .get("tool")
497	            .and_then(|t| t.get("poetry"))
498	            .and_then(|p| p.get("dependencies"))
499	            .and_then(|d| d.as_table_like())
500	        {
501	            for (name, item) in table.iter() {
502	                if name == "python" {
503	                    continue;
504	                }
505	                // `as_table_like()` covers inline and dotted tables, which parse to different
506	                // `Item` variants; both must be recognized or the dependency vanishes.
507	                let raw_req = match item {
508	                    toml_edit::Item::Value(toml_edit::Value::String(s)) => Some(s.value().as_str()),
509	                    _ => item
510	                        .as_table_like()
511	                        .and_then(|t| t.get("version"))
512	                        .and_then(|v| v.as_str()),
513	                };
514	
515	                let spec = match raw_req {
516	                    Some(req_str) => {
517	                        // Normalize Poetry caret/tilde/wildcard syntax to PEP 440, which
518	                        // `pep440_rs` cannot parse directly.
519	                        let normalized = normalize_poetry_version_spec(req_str);
520	                        match VersionReq::parse(&normalized, Ecosystem::Pypi) {
521	                            Ok(spec) => DepSpec::Range(spec, req_str.to_string()),
522	                            // Unrepresentable syntax stays visible in the graph as an opaque spec.
523	                            Err(_) => DepSpec::Opaque(req_str.to_string()),
524	                        }
525	                    }
526	                    // No `version` key: a path/git/url dependency or unrecognized shape;
527	                    // it must still appear in the graph.
528	                    None => {
529	                        DepSpec::Opaque("non-versioned dependency (path/git/url or unrecognized shape)".to_string())
530	                    }
531	                };
532	
533	                entries.push(DependencyEntry {
534	                    name: name.to_string(),
535	                    package_name: name.to_string(),
536	                    inherited: false,
537	                    kind: DepKind::Runtime,
538	                    spec,
539	                    locator: DepLocator::python(DepContainer::PoetryDependencies, None),
540	                });
541	            }
542	        }
543	
544	        Box::new(entries.into_iter())
545	    }
