547	    fn update_dependency_spec(
548	        &mut self,
549	        name: &str,
550	        kind: DepKind,
551	        at: &DepLocator,
552	        new: DepSpec,
553	        _permit: &ApplyPermit,
554	    ) -> Result<(), ManifestError> {
555	        let new_spec_str = match new {
556	            DepSpec::Range(req, _) => req.render().to_string(),
557	            DepSpec::Exact(v) => format!("=={}", v.render()),
558	            _ => return Ok(()),
559	        };
560	        let not_found = || ManifestError::DependencyNotFound {
561	            path: self.path.clone(),
562	            name: name.to_string(),
563	            kind,
564	        };
565	
566	        let DepLocator::Python {
567	            container, position, ..
568	        } = at
569	        else {
570	            return Err(not_found());
571	        };
572	        match container {
573	            DepContainer::PoetryDependencies => {
574	                let table = self
575	                    .document
576	                    .get_mut("tool")
577	                    .and_then(|t| t.get_mut("poetry"))
578	                    .and_then(|p| p.get_mut("dependencies"))
579	                    .and_then(|d| d.as_table_like_mut())
580	                    .ok_or_else(not_found)?;
581	                // Edited in place, so the comment above the dependency and the one after it stay.
582	                if table.get(name).ok_or_else(not_found)?.is_table_like() {
583	                    let fields = table
584	                        .get_mut(name)
585	                        .and_then(|existing| existing.as_table_like_mut())
586	                        .ok_or_else(not_found)?;
587	                    crate::common::set_scalar_preserving_decor(fields, "version", &new_spec_str);
588	                } else {
589	                    crate::common::set_scalar_preserving_decor(table, name, &new_spec_str);
590	                }
591	            }
592	            container => {
593	                let position = position.ok_or_else(not_found)?;
594	                let requirements = match container {
595	                    DepContainer::ProjectDependencies => {
596	                        self.document.get_mut("project").and_then(|p| p.get_mut("dependencies"))
597	                    }
598	                    DepContainer::Extra(extra) => self
599	                        .document
600	                        .get_mut("project")
601	                        .and_then(|p| p.get_mut("optional-dependencies"))
602	                        .and_then(|d| d.get_mut(extra.as_str())),
603	                    _ => None,
604	                }
605	                .and_then(|item| item.as_array_mut())
606	                .ok_or_else(not_found)?;
607	                // The array may differ from the one the locator was read from: refuse to rewrite another dependency.
608	                let rewritten = requirements
609	                    .get(position)
610	                    .and_then(|item| item.as_str())
611	                    .and_then(|full_req| rewrite_requirement(full_req, name, &new_spec_str))
612	                    .ok_or_else(not_found)?;
613	                requirements.replace(position, rewritten);
614	            }
615	        }
616	
617	        Ok(())
618	    }
