699	/// Rewrites a PEP 508 dependency constraint to pin it to `target`.
700	///
701	/// The following single-clause and two-clause forms are recognized and rewritten:
702	///
703	/// - `==X.Y.Z` — exact pin — is rewritten to `==NEW`.
704	/// - `~=X.Y.Z` — compatible release — is rewritten to `~=NEW`.
705	/// - `>=X.Y.Z` — lower bound only — is rewritten to `>=NEW`.
706	/// - `>=X.Y.Z,<A.B` — two-clause range — is rewritten to `>=NEW,<NEXT_MAJOR`
707	///   where `NEXT_MAJOR` equals `target.major() + 1`.
708	///
709	/// A target in a non-zero PEP 440 epoch carries `N!` on every bound written.
710	///
711	/// A pre-release or dev/local target (e.g. a `snapshot` version) is rendered
712	/// in full rather than truncated to `major.minor.patch`, the same precision
713	/// rule `cargo::round_trip` applies for SemVer.
714	///
715	/// All other forms return `None` — including upper-bound-only (`<`, `<=`),
716	/// exclusion (`!=`), compound expressions beyond the two-clause range above,
717	/// and wildcard `*`. Callers must leave the original constraint unchanged
718	/// when `None` is returned.
719	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
720	    // Only Range specs are produced by iter_dependencies for Python.
721	    let original = match spec {
722	        DepSpec::Range(_, raw) => raw.as_str(),
723	        _ => return None,
724	    };
725	
726	    let trimmed = original.trim();
727	
728	    // Compound range: ">=X.Y.Z,<A.B" → ">=NEW,<NEXT_MAJOR"
729	    if trimmed.contains(',') {
730	        return rewrite_range(trimmed, target);
731	    }
732	
733	    // Single-clause forms matched by their PEP 508 operator prefix.
734	    if trimmed.starts_with("==") {
735	        return rewrite_single(trimmed, "==", target);
736	    }
737	    if trimmed.starts_with("~=") {
738	        return rewrite_single(trimmed, "~=", target);
739	    }
740	    if trimmed.starts_with(">=") {
741	        return rewrite_single(trimmed, ">=", target);
742	    }
743	    // Poetry's own operators: bare caret and tilde (PEP 440's `~=` was handled above).
744	    if let Some(core) = trimmed.strip_prefix('^') {
745	        return rewrite_poetry_operator("^", core, target);
746	    }
747	    if let Some(core) = trimmed.strip_prefix('~').filter(|rest| !rest.starts_with('=')) {
748	        return rewrite_poetry_operator("~", core, target);
749	    }
750	
751	    // Unknown or unsupported form (e.g. "<", "<=", "!=", bare "*").
752	    None
753	}
754	
755	/// Rewrites a single-clause PEP 508 specifier, preserving the operator.
756	fn rewrite_single(original: &str, op: &str, target: &Version) -> Option<DepSpec> {
757	    // Validate that the original clause parses correctly (guards against
758	    // unknown version syntax that happens to start with a known prefix).
759	    let rest = original.strip_prefix(op)?;
760	    // A wildcard (`==1.*`) or arbitrary-equality (`===1.2.3`) clause has no exact form to rewrite without changing
761	    // its meaning, so it is left for the caller to reject like any other form it cannot rewrite.
762	    if rest.contains('*') || rest.trim_start().starts_with(['=', '<', '>', '~', '!']) {
763	        return None;
764	    }
765	    let mut rendered_target = render_target(op, target)?;
766	    // `~=1.2` allows any 1.x from 1.2, and `~=1.2.0` only 1.2.x, so a compatible-release clause keeps the number of
767	    // components it was written with.
768	    if op == "~="
769	        && !target.is_prerelease()
770	        && parse_release_core(rest.trim()).is_some_and(|(_, (_, minor, patch))| minor.is_some() && patch.is_none())
771	    {
772	        rendered_target = format!("{}{}.{}", epoch_prefix(target), target.major()?, target.minor()?);
773	    }
774	    let rendered = format!("{op}{rendered_target}");
775	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
776	    Some(DepSpec::Range(req, rendered))
777	}
