779	/// Rewrites a Poetry caret or tilde clause to the same window around the stable `target`; the caller writes it as the
780	/// equivalent PEP 440 range, which Poetry reads too. A pre-release target has no caret or tilde form, so it is left alone.
781	fn rewrite_poetry_operator(op: &str, core: &str, target: &Version) -> Option<DepSpec> {
782	    parse_version_core(core)?;
783	    if target.is_prerelease() {
784	        return None;
785	    }
786	    let rendered = format!("{op}{}", render_target(op, target)?);
787	    let req = VersionReq::parse(&normalize_poetry_version_spec(&rendered), Ecosystem::Pypi).ok()?;
788	    Some(DepSpec::Range(req, rendered))
789	}
