791	/// Renders `target` at the precision a rewritten spec should carry, for use after `op`:
792	/// `[N!]major.minor.patch` for a stable release; the version in full for a pre-release or
793	/// dev target paired with `==`/`!=` (the only operators PEP 440 allows on a local version);
794	/// the version with its local segment stripped for every other operator, since PEP 440
795	/// forbids `>=`, `<=`, `>`, `<` and `~=` from carrying one.
796	fn render_target(op: &str, target: &Version) -> Option<String> {
797	    if target.is_prerelease() {
798	        let full = target.render();
799	        if op == "==" || op == "!=" {
800	            return Some(full.to_string());
801	        }
802	        return Some(full.split('+').next().unwrap_or(full).to_string());
803	    }
804	    Some(format!(
805	        "{}{}.{}.{}",
806	        epoch_prefix(target),
807	        target.major()?,
808	        target.minor()?,
809	        target.patch()?
810	    ))
811	}
812	
813	/// `N!` for a version in epoch `N`, empty for epoch 0. Every bound written for a target needs it: an epoch outranks the
814	/// whole release segment, so a bound without it sits in epoch 0 and does not bound the target's epoch.
815	fn epoch_prefix(target: &Version) -> String {
816	    match target.epoch() {
817	        0 => String::new(),
818	        epoch => format!("{epoch}!"),
819	    }
820	}
821	
822	/// Major, and the minor and patch when written.
823	type ReleaseCore = (u64, Option<u64>, Option<u64>);
824	
825	/// A clause's epoch and release core, to read the precision it was written at.
826	fn parse_release_core(s: &str) -> Option<(u64, ReleaseCore)> {
827	    let (epoch, release) = match s.split_once('!') {
828	        Some((epoch, release)) => (epoch.trim().parse().ok()?, release),
829	        None => (0, s),
830	    };
831	    Some((epoch, parse_version_core(release)?))
832	}
833	
834	/// Rewrites a two-clause `>=X.Y.Z,<A.B` range to `>=NEW,<NEXT_MAJOR`.
835	///
836	/// Returns `None` for anything that does not match exactly this two-clause
837	/// lower/upper pattern, including specs with three or more clauses (e.g.
838	/// `>=1.0,<2.0,!=1.5.0`) where silently dropping extra clauses would produce
839	/// a semantically incorrect constraint.
840	fn rewrite_range(original: &str, target: &Version) -> Option<DepSpec> {
841	    // Reject any spec with more than two comma-separated clauses: rewriting
842	    // would silently discard the extra clauses, changing the semantics.
843	    if original.split(',').count() != 2 {
844	        return None;
845	    }
846	
847	    let mut parts = original.splitn(2, ',');
848	    let lower = parts.next()?.trim();
849	    let upper = parts.next()?.trim();
850	
851	    // Lower clause must be `>=…`.
852	    if !lower.starts_with(">=") {
853	        return None;
854	    }
855	    // Upper clause must be strictly `<…` (not `<=`).
856	    if !upper.starts_with('<') || upper.starts_with("<=") {
857	        return None;
858	    }
859	
860	    // A window of one minor (`>=0.1.0,<0.2`) stays one minor wide; any other upper bound, including one in another
861	    // epoch, becomes the next major.
862	    let lower_core = lower
863	        .strip_prefix(">=")
864	        .and_then(|version| parse_release_core(version.trim()));
865	    let upper_core = upper
866	        .strip_prefix('<')
867	        .and_then(|version| parse_release_core(version.trim()));
868	    let one_minor_window = matches!(
869	        (lower_core, upper_core),
870	        (
871	            Some((lower_epoch, (lower_major, Some(lower_minor), _))),
872	            Some((upper_epoch, (upper_major, Some(upper_minor), upper_patch)))
873	        ) if upper_epoch == lower_epoch
874	            && upper_major == lower_major
875	            && upper_minor == lower_minor + 1
876	            && upper_patch.unwrap_or(0) == 0
877	    );
878	    let epoch = epoch_prefix(target);
879	    let upper_bound = if one_minor_window {
880	        format!("{epoch}{}.{}", target.major()?, target.minor()? + 1)
881	    } else {
882	        format!("{epoch}{}", target.major()? + 1)
883	    };
884	    let rendered = format!(">={},<{upper_bound}", render_target(">=", target)?);
885	    let req = VersionReq::parse(&rendered, Ecosystem::Pypi).ok()?;
886	    Some(DepSpec::Range(req, rendered))
887	}
