901	/// One PEP 508 requirement string as a dependency edge, or `None` when it names no package.
902	fn pep508_entry(full_req_str: &str, kind: DepKind, locator: DepLocator) -> Option<DependencyEntry> {
903	    // `Requirement::parse` couldn't extract even a package name (an empty string or a
904	    // marker-only fragment): there is no name to key an entry on.
