fn prepare_remote<R: CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    selected: &BTreeMap<ReleasePackageId, (&callisto_model::Package, Version)>,
    artifact_policy: Option<&ArtifactBuildPolicy>,
    remote: GitRemoteRequirement,
) -> Result<Option<PreparedGitRemote>, GraphError> {
    let requires_git_remote = selected.values().any(|(package, _)| package.is_release_point());
    let git_remote = match (requires_git_remote, remote) {
        (false, _) => None,
        (true, GitRemoteRequirement::Required) => Some(prepared_git_remote(&workspace.root, workspace.runner)?),
        (true, GitRemoteRequirement::OptionalForPreview) => optional_git_remote(&workspace.root, workspace.runner)?,
    };
    if let Some(policy) = artifact_policy {
        match git_remote.as_ref().and_then(|remote| remote.github_repository.as_ref()) {
            Some(remote) if remote != &policy.repository => {
                return Err(GraphError::ReleaseArtifactRepositoryMismatch {
                    configured: policy.repository.clone(),
                    remote: remote.clone(),
                });
            }
            Some(_) => {}
            // A preview has no effect to protect and `origin` is optional for it; the run itself still needs one.
            None if git_remote.is_none() && remote == GitRemoteRequirement::OptionalForPreview => {}
            None => {
                return Err(GraphError::ReleasePreconditionUnmet {
                    requirement: ReleasePreconditionRequirement::GitHubRemote,
                });
            }
        }
    }
    Ok(git_remote)
}

/// A prerelease publishes under the tag its first identifier names (`1.0.0-beta.2` -> `beta`), `next` when that is not a
/// plain word, and never `latest`; a stable version takes the registry default.
fn npm_dist_tag(version: &Version) -> Option<String> {
    if !version.is_prerelease() {
        return None;
    }
    let prerelease = version.render().split_once('-').map_or("", |(_, rest)| rest);
    let label: String = prerelease
        .chars()
        .take_while(char::is_ascii_alphabetic)
        .collect::<String>()
        .to_ascii_lowercase();
    Some(if label.is_empty() || label == "latest" {
        "next".to_string()
    } else {
        label
    })
}

