/// Crates `a` and `b`, npm packages `c` and `d`: Cargo `a -> b -> c` (`a_table` holds `a`'s edge to `b`) and npm
/// `c -> d -> a`. `b -> c` and `d -> a` name a package with no distribution in the declaring ecosystem, so they
/// wait for its other distribution and close a loop no single ecosystem holds.
fn fallback_loop_repo(a_table: &str) -> tempfile::TempDir {
    let cargo = |name: &str, table: &str| {
        format!("[package]\nname = \"{name}\"\nversion = \"1.0.0\"\nedition = \"2021\"\n{table}")
    };
    let npm = |name: &str, dependencies: &str| {
        format!(r#"{{"name":"{name}","version":"1.0.0","dependencies":{{{dependencies}}}}}"#)
    };
    let target = |name: &str, registry: &str| {
        format!("[[package]]\nmatch = \"cargo/{name}\"\npublish-to = [\"{registry}\"]\n")
    };
    repo_of(&[
        (
            "Cargo.toml".to_owned(),
            "[workspace]\nmembers = [\"a\", \"b\", \"c\", \"d\"]\nresolver = \"2\"\n".to_owned(),
        ),
        (
            "package.json".to_owned(),
            r#"{"name":"root","private":true,"workspaces":["a","b","c","d"]}"#.to_owned(),
        ),
        (
            "a/Cargo.toml".to_owned(),
            cargo(
                "a",
                &format!("{a_table}\nb = {{ path = \"../b\", version = \"1.0.0\" }}\n"),
            ),
        ),
        (
            "b/Cargo.toml".to_owned(),
            cargo("b", "[dependencies]\nc = { path = \"../c\", version = \"1.0.0\" }\n"),
        ),
        ("c/Cargo.toml".to_owned(), cargo("c", "")),
        ("d/Cargo.toml".to_owned(), cargo("d", "")),
        ("a/package.json".to_owned(), npm("a", "")),
        ("b/package.json".to_owned(), npm("b", "")),
        ("c/package.json".to_owned(), npm("c", r#""d":"^1.0.0""#)),
        ("d/package.json".to_owned(), npm("d", r#""a":"^1.0.0""#)),
        (
            "callisto.toml".to_owned(),
            [("a", "crates-io"), ("b", "crates-io"), ("c", "npm"), ("d", "npm")]
                .map(|(name, registry)| target(name, registry))
                .join("\n"),
        ),
    ])
}

fn fallback_loop_decision() -> ReleaseDecisionV1 {
    release(&[
        (Ecosystem::Cargo, "a", "1.0.0"),
        (Ecosystem::Cargo, "b", "1.0.0"),
        (Ecosystem::Npm, "c", "1.0.0"),
        (Ecosystem::Npm, "d", "1.0.0"),
    ])
}

